import React, { useState } from 'react';
import './styles.css';

function parseLines(text) {
  const lines = text.split('\n');
  const records = [];
  const invalid = [];
  lines.forEach((raw, i) => {
    if (raw.trim() === '') return;
    const lineNo = i + 1;
    const commaIndex = raw.indexOf(',');
    if (commaIndex === -1) {
      invalid.push({ lineNo, reason: '缺少逗号分隔' });
      return;
    }
    const name = raw.slice(0, commaIndex).trim();
    const scoreText = raw.slice(commaIndex + 1).trim();
    if (name === '') {
      invalid.push({ lineNo, reason: '姓名为空' });
      return;
    }
    if (scoreText === '' || Number.isNaN(Number(scoreText))) {
      invalid.push({ lineNo, reason: '分数不是数字' });
      return;
    }
    const score = Number(scoreText);
    if (score < 0 || score > 100) {
      invalid.push({ lineNo, reason: '分数超出 0 到 100' });
      return;
    }
    records.push({ name, score });
  });
  return { records, invalid };
}

export default function App() {
  const [text, setText] = useState('');
  const [records, setRecords] = useState([]);
  const [invalid, setInvalid] = useState([]);
  const [analyzed, setAnalyzed] = useState(false);

  const handleAnalyze = () => {
    const result = parseLines(text);
    setRecords(result.records);
    setInvalid(result.invalid);
    setAnalyzed(true);
  };

  const handleClear = () => {
    setText('');
    setRecords([]);
    setInvalid([]);
    setAnalyzed(false);
  };

  const count = records.length;
  const average =
    count === 0
      ? '—'
      : (records.reduce((sum, r) => sum + r.score, 0) / count).toFixed(2);
  const max = count === 0 ? '—' : String(Math.max(...records.map((r) => r.score)));

  return (
    <main className="app">
      <h1>成绩文本分析器</h1>
      <textarea
        data-testid="score-input"
        className="score-input"
        value={text}
        onChange={(e) => setText(e.target.value)}
        placeholder="每行一条：姓名,分数"
        rows={6}
      />
      <div className="actions">
        <button data-testid="analyze-button" type="button" onClick={handleAnalyze}>
          分析
        </button>
        <button data-testid="clear-button" type="button" onClick={handleClear}>
          清空
        </button>
      </div>
      {analyzed && (
        <>
          <table data-testid="valid-table" className="valid-table">
            <thead>
              <tr>
                <th>姓名</th>
                <th>分数</th>
              </tr>
            </thead>
            <tbody>
              {records.map((r, idx) => (
                <tr key={idx}>
                  <td>{r.name}</td>
                  <td>{r.score}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <section data-testid="stats-panel" className="stats-panel">
            <div className="stat">
              <span className="stat-label">有效人数</span>
              <span data-testid="stat-count" className="stat-value">{count}</span>
            </div>
            <div className="stat">
              <span className="stat-label">平均分</span>
              <span data-testid="stat-average" className="stat-value">{average}</span>
            </div>
            <div className="stat">
              <span className="stat-label">最高分</span>
              <span data-testid="stat-max" className="stat-value">{max}</span>
            </div>
          </section>
          <ul data-testid="invalid-list" className="invalid-list">
            {invalid.map((item) => (
              <li key={item.lineNo} data-testid="invalid-item" className="invalid-item">
                第 {item.lineNo} 行：{item.reason}
              </li>
            ))}
          </ul>
        </>
      )}
    </main>
  );
}

